def get_grundy(n, k):
    """Compute Grundy numbers for pile of size n with parameter k using memoization."""
    memo = {0: 0}

    def gf(x):
        if x in memo:
            return memo[x]

        reachable = set()

        # Transition 1: remove 1 cow -> state x-1
        reachable.add(gf(x - 1))

        # Transition 2: if x is even, replace with k piles of x/2
        if x % 2 == 0:
            half = x // 2
            if k % 2 == 1:  # odd k: XOR contribution is grundy(half)
                reachable.add(gf(half))
            # else k is even: XOR contribution is 0 (even number of same values XOR to 0)

        # Compute mex
        mex = 0
        while mex in reachable:
            mex += 1

        memo[x] = mex
        return mex

    return gf(n)


