    input_data = input_string.strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    a = [int(input_data[i]) for i in range(2, 2 + n)]

    # Helper function to compute Grundy numbers
    class GrundyCalculator:
        def __init__(self, k):
            self.k = k
            self.memo = {0: 0}

        def get_g(self, x):
            if x in self.memo:
                return self.memo[x]

            reachable = set()
            reachable.add(self.get_g(x - 1))

            if x % 2 == 0:
                half = x // 2
                if self.k % 2 == 1:
                    reachable.add(self.get_g(half))

            mex = 0
            while mex in reachable:
                mex += 1

            self.memo[x] = mex
            return mex

    # Compute XOR sum
    calc = GrundyCalculator(k)
    xor_sum = 0
    for x in a:
        xor_sum ^= calc.get_g(x)

    if xor_sum != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"


