    # For balanced sequences: total operations must be zero, and prefix sum never negative

    # Count positive and negative occurrences for each absolute value on fronts and backs
    front_pos = set()  # Card indices where front > 0
    front_neg = set()  # Card indices where front < 0
    back_pos = set()   # Card indices where back > 0
    back_neg = set()   # Card indices where back < 0

    for i, (a, b) in enumerate(cards):
        if a > 0:
            front_pos.add(i)
        else:
            front_neg.add(i)
        if b > 0:
            back_pos.add(i)
        else:
            back_neg.add(i)

    # For each absolute value k (1 to n), need exactly:
    # - One front positive k and one front negative -k
    # - One back positive k and one back negative -k

    # Check the counts for each absolute value on fronts
    count = [0] * (2 * n + 1)  # indexed 1 to 2n for count of abs values
    for i in range(2 * n):
        val = abs(cards[i][0])
        count[val] += 1

    if count != [0] + [2] * n:
        return "NO\n"

    # Similarly check for backs
    count = [0] * (2 * n + 1)
    for i in range(2 * n):
        val = abs(cards[i][1])
        count[val] += 1

    if count != [0] + [2] * n:
        return "NO\n"

    # Now attempt to find a valid ordering using greedy with backtracking
    used = [False] * (2 * n)

    def can_place(i, current_front, current_back):
        a, b = cards[i]
        new_front = current_front + a
        new_back = current_back + b
        return new_front >= 0 and new_back >= 0

    result = []
    visited = [False] * (2 * n)

    def backtrack(front_bal, back_bal, idx):
        if len(result) == 2 * n:
            return True
        if idx == 2 * n:
            return False

        for i in range(2 * n):
            if not visited[i] and can_place(i, front_bal, back_bal):
                a, b = cards[i]
                visited[i] = True
                result.append(i)
                if backtrack(front_bal + a, back_bal + b, idx + 1):
                    return True
                result.pop()
                visited[i] = False
        return False

    if backtrack(0, 0, 0):
        output = ["YES\n"]
        for i in result:
            a, b = cards[i]
            output.append(f"{a} {b}\n")
        return "".join(output)
    else:
        return "NO\n"

