    sink = 2 * n + 1
    INF = 10**9

    # Capacity graph
    capacity = [[0] * (2 * n + 2) for _ in range(2 * n + 2)]

    for i in range(n):
        capacity[source][i + 1] = a[i]

    for i in range(n):
        capacity[n + 1 + i][sink] = b[i]

    for u, v in edges:
        capacity[u][v] = INF
        capacity[v][u] = INF
    for i in range(1, n + 1):
