    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((x, y, d, t, e))

    from collections import defaultdict
    cell_transformers = defaultdict(set)

    for (x, y, d, t_start, e) in transformers:
        max_time = N + M - 2

        for t in range(t_start, max_time + 1):
            k = t - t_start
            pos_idx = k % 4

            if pos_idx == 0:
                tx, ty = x, y
            elif pos_idx == 1:
                tx, ty = x + d, y - d
            elif pos_idx == 2:
                tx, ty = x + d, y
            else:
                tx, ty = x, y + d

            if 0 <= tx < N and 0 <= ty < M:
                cell_transformers[(tx, ty, t)].add(e)

    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]
    dp[0][0] = 0

    for i in range(N):
        for j in range(M):
            t = i + j

            if i == 0 and j == 0:
                if (i, j, t) in cell_transformers:
                    dp[i][j] = sum(cell_transformers[(i, j, t)])
                continue

            dp[i][j] = INF
            if i > 0 and dp[i-1][j] != INF:
                dp[i][j] = min(dp[i][j], dp[i-1][j])
            if j > 0 and dp[i][j-1] != INF:
                dp[i][j] = min(dp[i][j], dp[i][j-1])

            if (i, j, t) in cell_transformers:
                dp[i][j] += sum(cell_transformers[(i, j, t)])

    result = dp[N - 1][M - 1]
    return str(int(result))

