def generate_lucky_numbers(limit):
    """Generate all lucky numbers up to limit using BFS on digits"""
    lucky = []
    queue = [4, 7]

    while queue:
        current = queue.pop(0)
        if current > limit:
            continue
        lucky.append(current)
        next4 = current * 10 + 4
        next7 = current * 10 + 7
        if next4 <= limit:
            queue.append(next4)
        if next7 <= limit:
            queue.append(next7)

    return lucky

def solution(input_str):
