class Solution:
    def solution(self, s):
        """
        Find the largest base b (1 < b < x) such that there exists a 
        rotatable number of length n under base b.
        """
        n, x = map(int, s.strip().split())
        p = n + 1

        # Check if p is prime - required for cyclic number of length n
        if not self._is_prime(p):
            return "-1\n"

        # n = p - 1, we need to find b where order(b, p) = n
        # This means b must NOT have any smaller order (proper divisor of n)

        # Get prime factors of n to efficiently find all proper divisors
        factors = self._get_prime_factors(n)
        all_divisors = self._get_divisors(n, factors)

        # Remove n itself from divisors (we only want proper divisors)
        proper_divisors = [d for d in all_divisors if d < n]

        # Search for largest valid b
        max_b_start = min(x - 1, n)

        for b in range(max_b_start, 1, -1):
            # Check if order(b, p) == n by ensuring b^d != 1 (mod p)
            # for all proper divisors d of n
            is_valid = True
            for d in proper_divisors:
                if pow(b, d, p) == 1:
                    is_valid = False
                    break

            if is_valid:
                return str(b) + "\n"

        return "-1\n"

    def _is_prime(self, n):
        """Check if n is prime"""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(n**0.5) + 1
        for i in range(3, limit, 2):
            if n % i == 0:
                return False
        return True

    def _get_prime_factors(self, n):
        """Get all prime factors of n"""
        factors = set()
        d = 2
        temp_n = n
        while d * d <= temp_n:
            while temp_n % d == 0:
                factors.add(d)
                temp_n //= d
            d += 1
        if temp_n > 1:
            factors.add(temp_n)
        return list(factors)

    def _get_divisors(self, factors, n):
        """Generate all divisors of n from its prime factors"""
        if not factors:
            return [1]

        factors = factors[:]*1  # Copy
        divisors = [1]
        for f in factors:
            new_divs = []
            for d in divisors:
                p = 1
                while True:
                    new_divs.append(d * p)
                    if p * f > n // d:
                        break
                    p *= f
            divisors.extend(new_divs)
        return sorted(divisors)

