                    # This must equal expected_sum (which is constant, so coef should be 0)
                    if current_sum_coef != 0:
                        # Constraint forms an equation that may not be satisfiable
                        # or forces a specific t
                        pass

        # After building component, check all edges for this component
        # to ensure consistency of constraints

        for u in visited:
            cu, const_u = model[u]
            for v, ctype in adj[u]:
                cv, const_v = model[v]

                if ctype == 1:
                    expected_sum = 1.0
                elif ctype == 2:
                    expected_sum = 2.0

                sum_coef = cu + cv
                sum_const = const_u + const_v

                # sum_coef * t + sum_const = expected_sum
                # This is only satisfiable if sum_coef == 0 and sum_const == expected
                # OR if we set t to satisfy it
                # Actually, since expected is constant, we need sum_coef = 0
                if abs(sum_coef) > 1e-9:
                    # Cannot satisfy constraint for any t - the edges conflict
                    # The cycle imposes incompatible constraints
                    return "NO"

                if abs(sum_const - expected_sum) > 1e-9:
                    return "NO"

        # Mark all nodes in visited as processed
        for node in visited:
            pass  # Already in model

    # Now build solution - minimize L1 norm
    # For each component, express all nodes as x[node] = coef * t + const
    # We need to find t that minimizes sum of abs(x[node])

    result_nodes = [0.0] * n
    for start in range(n):
        if start in model:
            continue

        model[start] = (1.0, 0.0)
        queue = deque([start])
        visited = {start}

        while queue:
            u = queue.popleft()
            for v, ctype in adj[u]:
                if v not in visited:
                    cv, const_v = model.get(v, (0, 0))
                    cu, const_u = model[u]
                    if ctype == 1:
                        model[v] = (-cu, 1.0 - const_u)
                    elif ctype == 2:
                        model[v] = (-cu, 2.0 - const_u)
                    visited.add(v)
                    queue.append(v)

        # For this component, find optimal t
        # cost(t) = sum over v in component of |coef[v]*t + const[v]|
        # This is piecewise linear, minimum at one of the breakpoints or at 0

        eps = 1e-9
        breakpoints = []

        for v in visited:
            c, const_v = model[v]
