                best_cost = cost
                best_t = t

        # Now compute assignments
        for v in visited:
            c, const_v = model[v]
            result_nodes[v] = c * best_t + const_v

    return "YES\n" + " ".join(f"{x:.2f}" for x in result_nodes)


