def compute_mec_radius(points):
    """
    Compute the radius of the minimum enclosing circle for a set of 2D points.
    """
    if len(points) == 1:
        return 0.0
    elif len(points) == 2:
        return distance(points[0], points[1]) / 2.0

    # For 3+ points, we need to find the MEC
    # The MEC of a set of points is either determined by:
    # 1. Two points (diameter case)
    # 2. Three points (circumcircle case)

    # Check all pairs and triples
    max_radius = 0.0

    # Check all pairs as diameter
    for i, p1 in enumerate(points):
        for j, p2 in enumerate(points):
            if i != j:
                radius = distance(p1, p2) / 2.0
                # Check if all points are within this radius from the midpoint
                midpoint = ((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0)
                if all(distance(midpoint, p) <= radius + 1e-9 for p in points):
                    max_radius = max(max_radius, radius)

    # Check all triples as circumcircle
    for i, p1 in enumerate(points):
