def circumcenter_of_triangle(triangle):
    """
    Compute the circumcenter of a triangle.
    Returns None if the triangle is degenerate.
    """
    (x1, y1), (x2, y2), (x3, y3) = triangle
    d = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
    if abs(d) < 1e-9:
        return None
    ux = ((x1 ** 2 + y1 ** 2) * (y2 - y3) + (x2 ** 2 + y2 ** 2) * (y3 - y1) + (x3 ** 2 + y3 ** 2) * (y1 - y2)) / d
    uy = ((x1 ** 2 + y1 ** 2) * (x3 - x2) + (x2 ** 2 + y2 ** 2) * (x1 - x3) + (x3 ** 2 + y3 ** 2) * (x2 - x1)) / d
    return (ux, uy)

def circumradius_of_triangle(triangle):
    """
    Compute the circumradius of a triangle.
    Returns 0 if the triangle is degenerate.
    """
    (x1, y1), (x2, y2), (x3, y3) = triangle
    a = distance((x1, y1), (x2, y2))
    b = distance((x2, y2), (x3, y3))
    c = distance((x3, y3), (x1, y1))
    if a < 1e-9 or b < 1e-9 or c < 1e-9 or (a + b < c) or (b + c < a) or (c + a < b):
        return 0.0
    s = (a + b + c) / 2.0
    area = math.sqrt(max(0, s * (s - a) * (s - b) * (s - c)))
    if area < 1e-9:
        return 0.0
    return (a * b * c) / (4 * area)

