def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = list(lines[1])

    # dp[i][bal] = whether position i is reachable with balance bal
    # bal is offset by n to be non-negative
    offset = n
    dp = [[False] * (2 * n + 1) for _ in range(n + 1)]
    path = [[None] * (2 * n + 1) for _ in range(n + 1)]  # stores prev_bal for backtracking

    dp[0][offset] = True

    for i in range(n):
        for bal in range(-(n - i), n + 1):
            if dp[i][bal + offset]:
                # Get allowed outcomes for current position
                outcomes = []
                if s[i] in ['?', 'W']:
                    outcomes.append((1, 'W'))
                if s[i] in ['?', 'L']:
                    outcomes.append((-1, 'L'))
                if s[i] in ['?', 'D']:
                    outcomes.append((0, 'D'))

                for change, char in outcomes:
                    new_bal = bal + change
                    # Cannot reach absolute k before the final position
                    if i < n - 1 and abs(new_bal) == k:
                        continue
                    dp[i + 1][new_bal + offset] = True
                    path[i + 1][new_bal + offset] = (bal, char)

    # Check endings at absolute k
    result_bals = []
    for bal in [-k, k]:
        if dp[n][bal + offset]:
            result_bals.append(bal)

    if not result_bals:
        return "NO"

    # Backtrack from one valid ending
    bal = result_bals[0]
    result = [''] * n

    for i in range(n, 0, -1):
        prev_bal, char = path[i][bal + offset]
        result[i - 1] = char
        bal = prev_bal

    return ''.join(result)

