    for i in range(2, 2 + n):
        grid.append(lines[i])

    # Create the actual mapping based on swaps
    # Normal mapping (no swaps)
    normal_map = {
        'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)
    }

    # Swapped mapping
    def get_mapping():
        mapping = {}
        if swapLR:
            # L and R are swapped
            reverse_lr = {'U': normal_map['U'], 
                         'D': normal_map['D'], 
                         'L': normal_map['R'], 
                         'R': normal_map['L']}
        else:
            reverse_lr = normal_map.copy()

        if swapUD:
            # U and D are swapped
            if swapLR:
                mapping = {
                    'U': reverse_lr['D'],
                    'D': reverse_lr['U'],
                    'L': reverse_lr['R'],
                    'R': reverse_lr['L']
                }
            else:
                mapping = {
                    'U': reverse_lr['D'],
                    'D': reverse_lr['U'],
                    'L': reverse_lr['L'],
                    'R': reverse_lr['R']
                }
        else:
            mapping = reverse_lr

        return mapping

    actual_mapping = get_mapping()

    # Find start (1,1) -> (0,0), finish and dangerous cells
    start = (0, 0)
    finish = None
    dangerous = set()

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish = (r, c)
            elif grid[r][c] == '*':
                dangerous.add((r, c))

    # BFS to find path to finish
    def bfs():
        queue = deque([(start, "")])
        visited = {start}

        while queue:
            (r, c), path = queue.popleft()

            if (r, c) == finish:
                return path

            for move in ['U', 'D', 'L', 'R']:
                dr, dc = actual_mapping[move]
                nr, nc = r + dr, c + dc

                # Check bounds
                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    continue

                # Check if position is dangerous
                if (nr, nc) in dangerous:
                    continue

                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + move))

        return None

    # Calculate the path
    path = bfs()
    if path:
        # Normalize the path output
        return '\n'.join(path) + '\n'
    else:
        return ""

