    tree_size = 4 * n
    min_tree = [float('inf')] * tree_size
    max_tree = [float('-inf')] * tree_size

    def build(arr, node, start, end):
        if start == end:
            min_tree[node] = max_tree[node] = arr[start]
        else:
            mid = (start + end) // 2
            build(arr, 2*node, start, mid)
            build(arr, 2*node+1, mid+1, end)
            min_tree[node] = min(min_tree[2*node], min_tree[2*node+1])
            max_tree[node] = max(max_tree[2*node], max_tree[2*node+1])

    build(x, 1, 0, n-1)

    def query_min(node, start, end, l, r):
        if r < start or end < l:
            return float('inf')
        if l <= start and end <= r:
            return min_tree[node]
        mid = (start + end) // 2
        return min(query_min(2*node, start, mid, l, r),
                  query_min(2*node+1, mid+1, end, l, r))

    def query_max(node, start, end, l, r):
        if r < start or end < l:
            return float('-inf')
        if l <= start and end <= r:
            return max_tree[node]
        mid = (start + end) // 2
        return max(query_max(2*node, start, mid, l, r),
                  query_max(2*node+1, mid+1, end, l, r))

    def span(l, r):
        if l > r:
            return 0
        return query_max(1, 0, n-1, l, r) - query_min(1, 0, n-1, l, r)

    results = []

