def solution(input_str):
    lines = input_str.strip().split('\n')
    n, s = map(int, lines[0].split())

    vi = []
    ci = []
    for line in lines[1:]:
        parts = line.split()
        vi.append(int(parts[0]))
        ci.append(int(parts[1]))

    def can_achieve(time_Limit):
        cur_cookies = 0
        cur_best_rate = vi[0] if n > 0 else 0
        bought = [False] * n

        # Sort buildings by efficiency (v/c ratio), descending
        eff_sorted = sorted(range(n), key=lambda i: float('inf') if ci[i] == 0 else vi[i] / ci[i], 
                           reverse=True)

        for t in range(time_Limit):
            if cur_cookies >= s:
                return True

            # Try to buy buildings in efficiency order
            for i in eff_sorted:
                if not bought[i] and cur_cookies >= ci[i]:
                    if vi[i] > cur_best_rate:
                        bought[i] = True
                        cur_cookies -= ci[i]
                        cur_best_rate = vi[i]
                        break

            # Accumulate cookies at current best rate
            if cur_best_rate == 0:
                cur_cookies += 0
            else:
                cur_cookies += cur_best_rate

        return cur_cookies >= s

    # Binary search for minimum time
    left, right = 1, s
    while left < right:
        mid = (left + right) // 2
        if can_achieve(mid):
            right = mid
        else:
            left = mid + 1

    return str(left) + '\n'
